/* package whatever; // don't place package name! */

import java.util.*;
import java.lang.*;
import java.io.*;

/* Name of the class has to be "Main" only if the class is public. */
public class Ideone
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner st=new Scanner (System.in);
		int l=st.nextInt(); char ch; String wd="";
		int max=0,num=0;
		String s=st.next();
		int i,j=0;
		for(i=0;i<l;i++)
		{
			ch=s.charAt(i);
			if(ch=='(')
			{
			max=(max>wd.length())?max:wd.length();	
				wd="";
				j=1;
			}
			else if(ch==')'){
				if(wd.length()!=0)
				num++;
			j=0;
			wd="";
			}
			else if(ch=='_')
			{
				if(j==1){
				if(wd.length()!=0)
				num++;}
				else
				max=(max>wd.length())?max:wd.length();
				wd="";
			}
			else{
			wd=wd+ch;
			if(i==l-1)
			max=(max>wd.length())?max:wd.length();
			}
			}
			System.out.println(max+" "+num);
		}

		// your code goes here
	}

